Select TAB.* from ( Select ContractNo, AR_Set_Customer.CustomerName, Set_Batch.Description As BatchDescription, Inv_Item.Description as ItemDescription, --Sal_OrderDetail.Quantity As ContractQuantity, SAL_OrderDetail.Quantity - isnull(SAL_OrderDetail.ReversedQuantity,0) as ContractQuantity, ( Select IsNull(Sum(Abs(TransactionQuantity)), 0) From Inv_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Inv_StockTransactionHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Inv_StockTransactionHeader.StockTransactionID = Inv_StockTransactionDetail.StockTransactionID AND Inv_StockTransactionHeader.Status = 1 And Inv_StockTransactionHeader.DocumentDate Between @FromDate And @ToDate Inner Join Sal_DeliveryOrderDetail On Sal_DeliveryOrderDetail.CompanyID = Inv_StockTransactionDetail.CompanyID AND Sal_DeliveryOrderDetail.PeriodID = Inv_StockTransactionDetail.PeriodID AND Sal_DeliveryOrderDetail.DOHeaderID = Inv_StockTransactionDetail.SourceHeaderID AND Sal_DeliveryOrderDetail.DODetailID = Inv_StockTransactionDetail.SourceLineID AND Sal_DeliveryOrderDetail.Status = 1 Inner Join Sal_DeliveryOrderHeader On Sal_DeliveryOrderHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Sal_DeliveryOrderHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Sal_DeliveryOrderHeader.DeliveryOrderID = Inv_StockTransactionDetail.SourceHeaderID AND Sal_DeliveryOrderHeader.DocumentTypeID = Inv_StockTransactionDetail.SourceDocumentTypeID AND Sal_DeliveryOrderHeader.DeliveryOrderNo = Inv_StockTransactionDetail.SourceCode AND Sal_DeliveryOrderHeader.Status = 1 Where Sal_DeliveryOrderDetail.CompanyID = Sal_OrderDetail.CompanyID AND Sal_DeliveryOrderDetail.PeriodID = Sal_OrderDetail.PeriodID AND Sal_DeliveryOrderDetail.SalesOrderHeaderID = Sal_OrderDetail.OrderID AND Sal_DeliveryOrderDetail.SalesOrderDetailID = Sal_OrderDetail.OrderDetailID AND Inv_StockTransactionDetail.Status = 1 ) As QuantityToDay, ( Select IsNull(Sum(Abs(TransactionQuantity)), 0) From Inv_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Inv_StockTransactionHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Inv_StockTransactionHeader.StockTransactionID = Inv_StockTransactionDetail.StockTransactionID AND Inv_StockTransactionHeader.Status = 1 And Inv_StockTransactionHeader.DocumentDate <= @ToDate Inner Join Sal_DeliveryOrderDetail On Sal_DeliveryOrderDetail.CompanyID = Inv_StockTransactionDetail.CompanyID AND Sal_DeliveryOrderDetail.PeriodID = Inv_StockTransactionDetail.PeriodID AND Sal_DeliveryOrderDetail.DOHeaderID = Inv_StockTransactionDetail.SourceHeaderID AND Sal_DeliveryOrderDetail.DODetailID = Inv_StockTransactionDetail.SourceLineID AND Sal_DeliveryOrderDetail.Status = 1 inner join SAL_DispatchHeader on SAL_DispatchHeader.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID and SAL_DispatchHeader.CompanyID = Inv_StockTransactionHeader.CompanyID AND SAL_DispatchHeader.PeriodID = Inv_StockTransactionHeader.PeriodID and Inv_stockTransactionHeader.DocumentNo =SAL_DispatchHeader.DispatchNo and SAL_DispatchHeader.Status =1 Where Sal_DeliveryOrderDetail.CompanyID = Sal_OrderDetail.CompanyID AND Sal_DeliveryOrderDetail.PeriodID = Sal_OrderDetail.PeriodID AND Sal_DeliveryOrderDetail.SalesOrderHeaderID = Sal_OrderDetail.OrderID AND Sal_DeliveryOrderDetail.SalesOrderDetailID = Sal_OrderDetail.OrderDetailID AND Inv_StockTransactionDetail.Status = 1 ) As QuantityToDate, ( Select IsNull(Sum(Abs(TransactionQuantity)), 0) From Inv_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Inv_StockTransactionHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Inv_StockTransactionHeader.StockTransactionID = Inv_StockTransactionDetail.StockTransactionID AND Inv_StockTransactionHeader.Status = 1 And Inv_StockTransactionHeader.DocumentDate < @FromDate Inner Join Set_DocumentType On Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1 Inner Join ApplicationMenu On ApplicationMenu.MenuID = Set_DocumentType.MenuID And ApplicationMenu.MenuPath = @MenuPath Where Inv_StockTransactionDetail.CompanyID = Sal_OrderHeader.CompanyID AND Inv_StockTransactionDetail.PeriodID = Sal_OrderHeader.PeriodID AND Inv_StockTransactionDetail.Status = 1 AND Inv_StockTransactionHeader.BatchID = Sal_OrderHeader.Season AND Inv_StockTransactionDetail.ItemID = Sal_OrderDetail.ItemID ) As PreviousProduction, ( Select IsNull(Sum(Abs(TransactionQuantity)), 0) From Inv_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Inv_StockTransactionHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Inv_StockTransactionHeader.StockTransactionID = Inv_StockTransactionDetail.StockTransactionID AND Inv_StockTransactionHeader.Status = 1 And Inv_StockTransactionHeader.DocumentDate Between @FromDate And @ToDate Inner Join Set_DocumentType On Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1 Inner Join ApplicationMenu On ApplicationMenu.MenuID = Set_DocumentType.MenuID And ApplicationMenu.MenuPath = @MenuPath Where Inv_StockTransactionDetail.CompanyID = Sal_OrderHeader.CompanyID AND Inv_StockTransactionDetail.PeriodID = Sal_OrderHeader.PeriodID AND Inv_StockTransactionDetail.Status = 1 AND Inv_StockTransactionHeader.BatchID = Sal_OrderHeader.Season AND Inv_StockTransactionDetail.ItemID = Sal_OrderDetail.ItemID ) As TodayProduction From Sal_OrderHeader Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = Sal_OrderHeader.PeriodID --AR_Set_Customer.CompanyID = Sal_OrderHeader.CompanyID AND AND AR_Set_Customer.CustomerID = Sal_OrderHeader.CustomerID Inner Join Set_Batch On Set_Batch.PeriodID = Sal_OrderHeader.PeriodID AND Set_Batch.BatchID = Sal_OrderHeader.Season Inner Join Sal_OrderDetail On Sal_OrderDetail.CompanyID = Sal_OrderHeader.CompanyID AND Sal_OrderDetail.PeriodID = Sal_OrderHeader.PeriodID AND Sal_OrderDetail.OrderID = Sal_OrderHeader.OrderID AND Sal_OrderDetail.Status = 1 Inner Join Inv_Item On Inv_Item.ItemID = Sal_OrderDetail.ItemID AND Inv_Item.InvoiceableItemFlag = 1 Where Sal_OrderHeader.CompanyID = @CompanyID AND Sal_OrderHeader.PeriodID = @PeriodID AND Sal_OrderHeader.Status = 1 {0} ) as TAB {1}
--Godown Query--
Select Isnull(Sum(Inv_StockTransactionDetail.TransactionQuantity), 0) Quantity, INV_Item.Description As ItemName, Inv_StockTransactionHeader.LocationID, Set_Location.LocationName, Set_Batch.Description As BatchDescription From Inv_StockTransactionDetail Inner JOIN Inv_StockTransactionHeader on Inv_StockTransactionHeader.CompanyID = Inv_StockTransactionDetail.CompanyID AND Inv_StockTransactionHeader.PeriodID = Inv_StockTransactionDetail.PeriodID AND Inv_StockTransactionHeader.StockTransactionID = Inv_StockTransactionDetail.StockTransactionID AND Inv_StockTransactionHeader.Status = 1 Inner JOIN INV_Item on INV_Item.ItemID = Inv_StockTransactionDetail.ItemID AND Inv_Item.InvoiceableItemFlag = 1 Inner JOIN Set_Location on Set_Location.LocationID = INV_StockTransactionHeader.LocationID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1 AND Set_DocumentType.TransactionImpact <> 'No Impact' Inner Join Set_Batch On Set_Batch.PeriodID = Inv_StockTransactionHeader.PeriodID AND Set_Batch.BatchID = Inv_StockTransactionHeader.BatchID Where Inv_StockTransactionDetail.CompanyID = @CompanyID AND Inv_StockTransactionDetail.PeriodID = @PeriodID AND (Inv_StockTransactionDetail.ItemID = @ItemID OR @ItemID Is NULL) Group By INV_StockTransactionHeader.LocationID, Inv_StockTransactionDetail.ItemID, INV_StockTransactionHeader.BatchID, INV_Item.Description, Set_Location.LocationName, Set_Batch.Description
